density_code:
Clear[r, d, a, b, z];
density = 2^(1-d/2) r^(d-1) Exp[-r^2/2]/Gamma[d/2];
normalization = Integrate[density, {r,0,Infinity}, Assumptions -> d>0];
tailDerivative = FullSimplify[-D[Gamma[d/2,r^2/2]/Gamma[d/2],r]-density, Assumptions -> d>0 && r>0];
mass = Exp[-1/2]-Exp[-2]+Exp[-9/2];
example = N[Exp[-(16/5)^2/2]/mass, 25];
rankLaw = Table[{bb, aa, Floor[aa (bb+1)]/(bb+1)}, {bb,{99,199}}, {aa,{1/100,1/20}}];
ExportString[<|"chiDensityNormalized"->normalization,"tailDerivativeResidual"->tailDerivative,"disconnectedRegion"->{{1,2},{3,"Infinity"}},"exampleRadius"->16/5,"exampleDf"->2,"conditionalTail"->example,"nominalTail"->N[Exp[-(16/5)^2/2],25],"exchangeableRankRejectionProbabilities"->rankLaw|>,"RawJSON"]

rank_code:
Clear[k, a, q]; n=999;
size[q_,a_] := Sum[PDF[BinomialDistribution[n,q],k] Floor[a (k+1)]/(k+1),{k,0,n}];
ExportString[<|"fixedProposalCount"->n,"nullRejectionProbability"->Table[<|"acceptanceProbability"->N[q],"alpha"->N[a],"size"->N[size[q,a],16]|>,{q,{1/100,1/50,1/10}},{a,{1/100,1/20}}],"minimumPWithZeroAccepted"->1,"assumption"->"Conditional on A,u,M and K accepted proposals, the observed radius and the K accepted radii are exchangeable. K is generated with a fixed proposal count and independent randomness."|>,"RawJSON"]

